source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R')
plan<-rd('model_plan.tsv');st<-rd('nichenet_analysis_status.tsv');bg<-rd('nichenet_backgrounds.tsv.gz');m20<-scan(file.path(P,'neighborhood_mp10_calibration_v5/01_score_fidelity/top20.txt'),what='character',quiet=TRUE);targ<-list();checks<-list();keys<-unique(st[,.(model_id,mask,target_direction)])
for(i in seq_len(nrow(keys))){k<-keys[i];f<-tb(paste0('de/',k$model_id,'.tsv.gz'));if(!file.exists(f))next;d<-fread(f);bb<-bg[model_id==k$model_id&mask==k$mask,gene];z<-d[FDR<.05&if(k$target_direction=='positive')logFC>0 else if(k$target_direction=='negative')logFC<0 else TRUE];z<-z[gene%in%bb];z[,`:=`(model_id=k$model_id,mask=k$mask,target_direction=k$target_direction)];targ[[i]]<-z;expected<-unique(st[model_id==k$model_id&mask==k$mask&target_direction==k$target_direction,n_targets]);checks[[i]]<-data.table(model_id=k$model_id,mask=k$mask,target_direction=k$target_direction,n_targets=nrow(z),expected=paste(expected,collapse=';'),subset_background=all(z$gene%in%bb),masked_excludes_M20=k$mask!='M20-masked'||!any(c(bb,z$gene)%in%m20),count_matches=length(expected)==1&&!is.na(expected)&&expected==nrow(z))}
put(rbindlist(targ,fill=TRUE),'nichenet_targets.tsv.gz');put(rbindlist(checks,fill=TRUE),'nichenet_target_background_checks.tsv');stopifnot(all(rbindlist(checks)$subset_background),all(rbindlist(checks)$masked_excludes_M20),all(rbindlist(checks)$count_matches))
# Direct per-dataset paired descriptions remain available even when formal small-n DE is NE.
e<-rd('candidate_expression_detection.tsv.gz');pr<-rd('pseudobulk_profiles.tsv');out<-list()
for(h in c('H50','H10','H05'))for(g in unique(e$gene)){
 hi<-e[status=='computed'&main_patient&profile_type==h&gene==g&n_cells>=50,.(sample_uid,dataset,high=normalized_mean,high_detection=positive_fraction)];lo<-e[status=='computed'&main_patient&profile_type=='L50'&gene==g&n_cells>=50,.(sample_uid,low=normalized_mean,low_detection=positive_fraction)];z<-merge(hi,lo,by='sample_uid');if(!nrow(z))next;z<-z[,.(n_pairs=.N,mean_paired_difference=mean(high-low),median_paired_difference=median(high-low),fraction_positive=mean(high>low),mean_detection_difference=mean(high_detection-low_detection)),by=dataset];z[,`:=`(high_definition=h,gene=g,scope='descriptive_paired_normalized_expression',P_value_interpretation='no inferential P in this descriptive table')];out[[paste(h,g)]]<-z
};put(rbindlist(out),'candidate_dataset_paired_descriptive.tsv')
# Domain and complex information, without treating complex identifiers as measured genes.
