cx<-fread(file.path(HDEF,'tables/DB_complex.tsv'));co<-fread(file.path(HDEF,'tables/DB_cofactor.tsv'));put(cx[definition_id=='FLT1_KDR'],'VEGF_complex_definition.tsv');put(co[definition_id=='VEGF activation receptor'],'VEGF_cofactor_definition.tsv')
